#!/usr/bin/env tsx

// Test script for typing database table methods using an external type
// declaration file for a sample database, generated by ./typegen.ts.
// The ColumnsForTableMethod utility type has been extended to allow the
// MusicDatabase specific type to be passed as the first generic Model
// parameter
import { MusicDatabase } from '../tmp/musicDatabase'

type TableMethod = 'select' | 'insert' | 'update' | 'delete'
type AnyTable = Record<TableMethod, AnyTableColumns>
type AnyTableColumns = Record<string, any>
type AnyDatabase = {
  // More to go here
  tables: Record<string, AnyTable>
}
type ColumnsForTableMethod<
  Model extends AnyDatabase,
  TableName extends keyof Model['tables'],
  Method extends TableMethod
> =
  Model['tables'][TableName][Method]


function database<Model extends AnyDatabase>() {
  function table<Name extends keyof Model['tables']>(
    name: Name
  ) {
    return {
      insert: function(
        setColumns: ColumnsForTableMethod<Model, Name, 'insert'>,
      ) {
        return 'Fake insert'
      },
      update: function(
        setColumns: ColumnsForTableMethod<Model, Name, 'update'>,
        whereColumns: ColumnsForTableMethod<Model, Name, 'select'>
      ) {
        return 'Fake update'
      },
      select: function(
        whereColumns: ColumnsForTableMethod<Model, Name, 'select'>
      ) {
        return 'Fake select'
      },
      'delete': function(
        whereColumns: ColumnsForTableMethod<Model, Name, 'delete'>,
      ) {
        return 'Fake delete'
      },
    }
  }
  return { table }
}

// This is where we apply the MusicDatabase type to our generic database
const db = database<MusicDatabase>()

// The table names are now strictly typed, in this case to `artists` and `albums`
const artists = db.table('artists')

// Each of the methods now has typed arguments (of a form).  The parameters
// passed to each method must meet the required type.  For example, you
// can't include properties in the first argument to insert() for columns that
// don't exists or a read only.  You can't update columns via update() if they're
// read only.  You must specify the 'id' identifier column for the delete() method.
const response1 = artists.insert({ id: 11, name: 'Spinal Tap', volume: 11 })
const response2 = artists.update({ name: 'Spin̈al Tap' }, { id: 11 })
const response3 = artists.select({ id: 11 })
const response4 = artists.select({ volume: 11 })
const response5 = artists.delete({ id: 11 })

